```rust
use reqwest::Client;

// Consulta os dois endpoints em paralelo e devolve os corpos
pub async fn fetch_both(url_a: &str, url_b: &str) -> reqwest::Result<(String, String)> {
    let client = Client::new();

    let get = |url: String| {
        let client = client.clone();
        async move { client.get(url).send().await?.error_for_status()?.text().await }
    };

    tokio::try_join!(get(url_a.to_owned()), get(url_b.to_owned()))
}
```

